import java.util.Scanner;

public class Main {
    static final long MOD_CONST = 1000000007;

    static class MatrixType {
        long[][] matrix;
        int dimension;

        MatrixType(int size) {
            this.dimension = size;
            this.matrix = new long[size][size];
        }

        static MatrixType multiply(MatrixType A, MatrixType B) {
            MatrixType C = new MatrixType(A.dimension);
            for (int i = 0; i < A.dimension; ++i) {
                for (int j = 0; j < A.dimension; ++j) {
                    C.matrix[i][j] = 0;
                    for (int k = 0; k < A.dimension; ++k) {
                        C.matrix[i][j] += A.matrix[i][k] * B.matrix[k][j];
                    }
                    C.matrix[i][j] %= MOD_CONST;
                }
            }
            return C;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n_input = sc.nextLong();
        long m_input = sc.nextLong();

        int size = (int) (m_input + 1);
        MatrixType baseMatrix = new MatrixType(size);
        MatrixType identityMatrix = new MatrixType(size);

        for (int i = 0; i <= m_input; ++i) {
            baseMatrix.matrix[i][i] = 1;
            baseMatrix.matrix[0][i] = 1;
            identityMatrix.matrix[i][i] = 1;
        }

        long yVal = 1, yPow = 1;
        int levelIdx = 0;
        long total = 0;

        while (yPow * m_input <= n_input) {
            yPow *= m_input;
            levelIdx++;
        }

        // Initialize biMatrices
        MatrixType[][] biMatrices = new MatrixType[levelIdx + 1][(int) (m_input + 1)];
        for (int t = 0; t <= levelIdx; ++t) {
            for (int i = 0; i <= m_input; ++i) {
                biMatrices[t][i] = new MatrixType(size);
            }
        }

        for (int t = 0; t <= levelIdx; ++t) {
            if (t > 0) {
                biMatrices[t][0] = biMatrices[t - 1][0];
                for (int i = 1; i <= m_input; ++i) {
                    biMatrices[t][0] = MatrixType.multiply(biMatrices[t][0], biMatrices[t - 1][i]);
                }
            }
            for (int i = 1; i <= m_input; ++i) {
                // Copy previous matrix
                for (int j = 0; j < size; ++j) {
                    System.arraycopy(biMatrices[t][i - 1].matrix[j], 0, biMatrices[t][i].matrix[j], 0, size);
                }
                // Swap rows
                for (int j = m_input - 2; j >= 0; --j) {
                    for (int k = 0; k <= m_input; ++k) {
                        long temp = biMatrices[t][i].matrix[j][k];
                        biMatrices[t][i].matrix[j][k] = biMatrices[t][i].matrix[j + 1][k];
                        biMatrices[t][i].matrix[j + 1][k] = temp;
                    }
                }
                // Swap columns
                for (int j = m_input - 2; j >= 0; --j) {
                    for (int k = 0; k <= m_input; ++k) {
                        long temp = biMatrices[t][i].matrix[k][j];
                        biMatrices[t][i].matrix[k][j] = biMatrices[t][i].matrix[k][j + 1];
                        biMatrices[t][i].matrix[k][j + 1] = temp;
                    }
                }
            }
        }

        MatrixType current = identityMatrix;
        while (total < n_input) {
            if (total + yPow <= n_input) {
                total += yPow;
                current = MatrixType.multiply(current, biMatrices[levelIdx][0]);
                yVal = (yVal + 1) % m_input;
            } else {
                yPow /= m_input;
                levelIdx--;
            }
        }

        long answerSum = 0;
        for (int i = 0; i <= m_input; ++i) {
            answerSum = (answerSum + current.matrix[i][(int) m_input]) % MOD_CONST;
        }
        System.out.println(answerSum);
        sc.close();
    }
}
